import { pixelRatio, register, colors } from "./manager.js";
export function canvasScene(container, draw, options = {}) {
  const canvas = document.createElement("canvas");
  canvas.setAttribute("aria-hidden", "true");
  container.append(canvas);
  const ctx = canvas.getContext("2d");
  let w = 1,
    h = 1,
    time = 0;
  function render(t, dt, still) {
    time = t;
    ctx.clearRect(0, 0, w, h);
    draw({ ctx, w, h, t, dt, still, colors: colors() });
  }
  const resize = new ResizeObserver(() => {
    w = Math.max(1, container.clientWidth);
    h = Math.max(1, container.clientHeight);
    const dpr = pixelRatio();
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    render(time, 0, true);
  });
  resize.observe(container);
  const stop = register(container, render, options);
  return {
    canvas,
    render: () => render(time, 0, true),
    destroy() {
      stop();
      resize.disconnect();
      canvas.remove();
    },
  };
}
export function arrow(ctx, x, y, dx, dy, color, width = 1.5) {
  const length = Math.hypot(dx, dy);
  if (length < 0.5) return;
  const angle = Math.atan2(dy, dx),
    size = Math.min(5, length * 0.32);
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + dx, y + dy);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(
    x + dx - size * Math.cos(angle - 0.5),
    y + dy - size * Math.sin(angle - 0.5),
  );
  ctx.lineTo(
    x + dx - size * Math.cos(angle + 0.5),
    y + dy - size * Math.sin(angle + 0.5),
  );
  ctx.fill();
}
